export default function ClaudeForLifePromptsPage({ searchParams }: PageProps) {
  const rawToken = searchParams.access_token;
  const token = Array.isArray(rawToken) ? rawToken[0] : rawToken;

  if (token !== ACCESS_TOKEN) {
    redirect("/shop");
  }

  return (
    <>
      <PromptPackContent
        eyebrow="Prompts"
        title="Claude for Life"
        description="Your Claude for Life prompts are ready below. Use Copy to grab each full prompt instantly."
        prompts={lifePrompts}
      />
      <div className="bg-[#F2F2F2] pb-16 text-center sm:pb-24">
        <Link
          href="/recover"
          className="text-sm font-medium text-neutral-600 underline underline-offset-4 hover:text-neutral-900"
        >
          Lost access? Recover it here
        </Link>
      </div>
    </>
  );
}
